r=.045;la=.02;d=.25;n=20;t=np.arange(1,n+1)*d;D=np.exp(-r*t);Q=np.exp(-la*np.arange(n+1)*d);dq=Q[:-1]-Q[1:];prem=d*D*Q[1:];deft=.6*D*dq;ax.plot(t,prem,label='Premium annuity contribution',color=ACCENT);ax.plot(t,deft,label='Default-leg probability contribution',color=BAD);ax.set_xlabel('Payment time (years)');ax.set_ylabel('Present-value weight per quarter');ax.set_title('Survival weights premiums; default mass weights protection');ax.legend()
